    'text-anchor': o.anchor || 'middle',
    'dominant-baseline': 'central'
  });
  t.font({ family: o.family || 'Georgia, serif', size: o.size || 13 });
  if (o.fill) t.fill(o.fill);
  if (o.style) t.attr('font-style', o.style);
  if (o.weight) t.attr('font-weight', o.weight);
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  return t;
}

function layoutHeap(n) {
  var pos = {}, off = [160, 80, 40, 20, 12];
  pos[1] = { x: 380, y: 110, d: 0 };
  for (var i = 2; i <= n; i++) {
    var p = pos[i >> 1];
    var o = off[Math.min(p.d, off.length - 1)];
    pos[i] = { x: p.x + (i % 2 === 0 ? -o : o), y: p.y + 80, d: p.d + 1 };
  }
  return pos;
}

function heapViolations(v) {
  var out = [], n = v.length;
  for (var i = 1; i <= n; i++) {
    for (var c = 2 * i; c <= Math.min(2 * i + 1, n); c++) {
      if (v[c - 1] > v[i - 1]) { if (out.indexOf(i) < 0) out.push(i); if (out.indexOf(c) < 0) out.push(c); }
    }
  }
  return out;
}

/* ─────────── scene renderer (state in → picture out) ─────────── */
function renderScene(st) {
  gEdge.clear(); gArr.clear(); gNode.clear(); gOver.clear(); gCap.clear();
  var v = st.values, n = v.length, pos = layoutHeap(n);
  var hi = st.hi || [], hc = st.hiColor || COL.cmp, viol = st.viol || [];

  /* array bar */
  var cw = Math.min(34, 420 / n), ch = 27, x0 = 92, y0 = 16;
  lbl(gArr, 'A', x0 - 13, y0 + ch / 2, { style: 'italic', size: 17, anchor: 'end' });
  for (var i = 1; i <= n; i++) {
    var cx = x0 + (i - 1) * cw;
    var sc = COL.ink, sw = 1, fl = '#f2f2f2';
    if (st.focus === i) { sc = COL.focus; sw = 2.6; fl = '#d3d3d3'; }
    if (hi.indexOf(i) >= 0) { sc = hc; sw = 2.6; }
    var cell = gArr.rect(cw, ch).move(cx, y0).fill(fl).stroke({ color: sc, width: sw });
    lbl(gArr, v[i - 1], cx + cw / 2, y0 + ch / 2, { size: 14 });
    lbl(gArr, i, cx + cw / 2, y0 + ch + 9, { size: 8.5, fill: '#777', family: 'sans-serif' });
    attachCell(cell, i, v);
  }

  /* edges */
  for (i = 2; i <= n; i++) {
    var a = pos[i >> 1], b = pos[i];
    gEdge.line(a.x, a.y, b.x, b.y).stroke({ color: COL.ink, width: 1 });
  }

  /* nodes */
  for (i = 1; i <= n; i++) {
    var p = pos[i], isF = (st.focus === i), inHi = hi.indexOf(i) >= 0, bad = viol.indexOf(i) >= 0;
    var col = inHi ? hc : (bad ? COL.bad : COL.ink);
    var wid = (inHi || bad) ? 2.6 : 1.2;
    var c = gNode.circle(NR * 2).center(p.x, p.y).fill(isF ? COL.focus : COL.node).stroke({ color: col, width: wid });
    lbl(gNode, v[i - 1], p.x, p.y + 0.5, { size: 15, fill: isF ? '#ffffff' : '#111111' });
    var isLeft = (i % 2 === 0);
    var ix = (i === 1) ? p.x : (isLeft ? p.x - NR - 3 : p.x + NR + 3);
    var iy = (i === 1) ? p.y - NR - 11 : p.y - NR - 5;
    lbl(gNode, i, ix, iy, { size: 10.5, fill: '#333', anchor: (i === 1) ? 'middle' : (isLeft ? 'end' : 'start'), halo: true });
    attachNode(c, i, v, n);
  }

  /* italic i marker */
  if (st.focus >= 1 && pos[st.focus]) {
    var pf = pos[st.focus];
    var lx = pf.x - NR - 9, anc = 'end';
    if (lx < 34) { lx = pf.x + NR + 9; anc = 'start'; }
    lbl(gOver, 'i', lx, pf.y, { style: 'italic', size: 15, anchor: anc, halo: true, fill: '#111' });
  }

  /* comparison arrows / swap arc */
  if (st.cmp && st.cmp.length === 2 && pos[st.cmp[0]] && pos[st.cmp[1]]) drawCompare(pos[st.cmp[0]], pos[st.cmp[1]]);
  if (st.swp && st.swp.length === 2 && pos[st.swp[0]] && pos[st.swp[1]]) drawSwap(pos[st.swp[0]], pos[st.swp[1]]);

  /* caption + badge + legend */
  lbl(gCap, st.caption || '', 60, 402, { anchor: 'start', size: 14, fill: '#111' });
  if (st.badge) {
    var bg = gCap.rect(272, 24).move(468, 390).radius(5).fill('#eef3ee').stroke({ color: '#555', width: 1 });
    lbl(gCap, 'max-heap: every parent \u2265 its children', 604, 402, { size: 11.5, family: 'sans-serif', fill: '#1b5e20' });
  } else if (st.badBadge) {
    gCap.rect(272, 24).move(468, 390).radius(5).fill('#fdeeee').stroke({ color: COL.bad, width: 1 });
    lbl(gCap, 'heap property violated (red circles)', 604, 402, { size: 11.5, family: 'sans-serif', fill: COL.bad });
  }
  drawLegend();
}

function drawCompare(a, b) {
  var dx = b.x - a.x, dy = b.y - a.y, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L, px = -uy, py = ux, k = 11;
  var x1 = a.x + ux * (NR + 4) + px * k, y1 = a.y + uy * (NR + 4) + py * k;
  var x2 = b.x - ux * (NR + 4) + px * k, y2 = b.y - uy * (NR + 4) + py * k;
  var ln = gOver.line(x1, y1, x2, y2).stroke({ color: COL.cmp, width: 1.8, dasharray: '4,3' });
  ln.marker('end', mkCmpEnd); ln.marker('start', mkCmpSta);
}

function drawSwap(a, b) {
  var mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
  var dx = b.x - a.x, dy = b.y - a.y, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L, px = -uy, py = ux;
  var s = (Math.abs(mx + px * 40 - 380) > Math.abs(mx - px * 40 - 380)) ? 1 : -1;
  var cxp = mx + px * 42 * s, cyp = my + py * 42 * s;
  var x1 = a.x + ux * (NR + 3), y1 = a.y + uy * (NR + 3);
  var x2 = b.x - ux * (NR + 3), y2 = b.y - uy * (NR + 3);
  var pth = gOver.path('M' + x1 + ',' + y1 + ' Q' + cxp + ',' + cyp + ' ' + x2 + ',' + y2)
    .fill('none').stroke({ color: COL.swp, width: 2 });
  pth.marker('end', mkSwpEnd); pth.marker('start', mkSwpSta);
}

function drawLegend() {
  var y = 436;
  gCap.circle(13).center(64, y).fill(COL.node).stroke({ color: COL.ink, width: 1 });
  lbl(gCap, 'untouched', 74, y, { anchor: 'start', size: 9.5, family: 'sans-serif', fill: '#444' });
  gCap.circle(13).center(140, y).fill(COL.focus).stroke({ color: COL.ink, width: 1 });
  lbl(gCap, 'current node i', 150, y, { anchor: 'start', size: 9.5, family: 'sans-serif', fill: '#444' });
  gCap.line(228, y, 246, y).stroke({ color: COL.cmp, width: 2, dasharray: '4,3' });
  lbl(gCap, 'comparison', 251, y, { anchor: 'start', size: 9.5, family: 'sans-serif', fill: '#444' });
  gCap.path('M320,' + y + ' Q331,' + (y - 9) + ' 342,' + y).fill('none').stroke({ color: COL.swp, width: 2 });
  lbl(gCap, 'swap', 347, y, { anchor: 'start', size: 9.5, family: 'sans-serif', fill: '#444' });
  gCap.circle(13).center(390, y).fill(COL.node).stroke({ color: COL.bad, width: 2 });
  lbl(gCap, 'heap violation', 400, y, { anchor: 'start', size: 9.5, family: 'sans-serif', fill: '#444' });
  lbl(gCap, 'array index i  \u2192  children 2i and 2i+1', 740, y, { anchor: 'end', size: 9.5, family: 'sans-serif', fill: '#888' });
}

/* ─────────── hover / click ─────────── */
function attachNode(c, i, v, n) {
  c.css('cursor', 'pointer');
  c.on('mousemove', function (e) {
    var kids = [];
    if (2 * i <= n) kids.push(v[2 * i - 1]);
    if (2 * i + 1 <= n) kids.push(v[2 * i]);
    showTooltip('index ' + i + ' \u00b7 key ' + v[i - 1] + (kids.length ? ' \u00b7 children ' + kids.join(', ') : ' \u00b7 leaf'), e);
  });
  c.on('mouseleave', hideTooltip);
  c.on('click', function () {
    showPopup('Node at index ' + i,
      'It holds key ' + v[i - 1] + '. Its parent is index ' + (i > 1 ? (i >> 1) : '\u2014') +
      ' and its children live at indices ' + (2 * i) + ' and ' + (2 * i + 1) + '. ' +
      'MAX-HEAPIFY(A, ' + i + ') compares this key with both children, swaps it with the larger child if either is bigger, and then keeps sinking from that child.');
  });
}
function attachCell(r, i, v) {
  r.css('cursor', 'pointer');
  r.on('mousemove', function (e) { showTooltip('A[' + i + '] = ' + v[i - 1] + ' \u2014 same element as tree node ' + i, e); });
  r.on('mouseleave', hideTooltip);
}

