/* ─────────── worker source ─────────── */
var WORKER_SRC = [
  "self.onmessage = function(e){",
  "  var code=e.data.code, base=e.data.arr, n=base.length;",
  "  var arr=[0]; for(var k=0;k<n;k++) arr.push(base[k]);",
  "  var frames=[], ops=0, MAXOPS=6000, MAXFR=2500, cur=0;",
  "  function snap(){ return arr.slice(1); }",
  "  function push(kind,idx,msg){ if(frames.length>=MAXFR) throw new Error('Frame cap ('+MAXFR+') hit - is the recursion terminating?'); frames.push({kind:kind,state:snap(),indices:idx||[],focus:cur,message:msg}); }",
  "  function chk(i){ if(typeof i!=='number'||!isFinite(i)||Math.floor(i)!==i||i<1||i>n) throw new Error('Index '+i+' is outside the valid range 1..'+n); return i; }",
  "  function tick(){ if(++ops>MAXOPS) throw new Error('Operation cap ('+MAXOPS+') exceeded - runaway loop?'); }",
  "  var value=function(i){tick();chk(i);return arr[i];};",
  "  var left=function(i){tick();return 2*i;};",
  "  var right=function(i){tick();return 2*i+1;};",
  "  var compare=function(i,j){tick();chk(i);chk(j);var r=arr[i]>arr[j];push('compare',[i,j],'compare A['+i+']='+arr[i]+' with A['+j+']='+arr[j]+' \\u2192 '+r);return r;};",
  "  var swap=function(i,j){tick();chk(i);chk(j);var a=arr[i],b=arr[j];arr[i]=b;arr[j]=a;push('swap',[i,j],'swap A['+i+']='+a+' with A['+j+']='+b);};",
  "  var focus=function(i){tick();chk(i);cur=i;push('focus',[i],'focus i='+i+' (key '+arr[i]+')');};",
  "  var note=function(t){tick();push('note',[],String(t));};",
  "  var err=null;",
  "  try{",
  "    var factory=new Function('value','left','right','compare','swap','focus','note', code+'\\n;return typeof maxHeapify===\"function\"?maxHeapify:null;');",
  "    var fn=factory(value,left,right,compare,swap,focus,note);",
  "    if(!fn) throw new Error('No function named maxHeapify was found. Define: function maxHeapify(i, heapSize){ ... }');",
  "    push('start',[],'BUILD-MAX-HEAP(A): n='+n+', heapify internal nodes '+Math.floor(n/2)+' down to 1');",
  "    for(var i=Math.floor(n/2);i>=1;i--){ cur=0; note('\\u2500\\u2500 MAX-HEAPIFY(A, '+i+') \\u2500\\u2500'); fn(i,n); }",
  "    cur=0; push('done',[],'BUILD-MAX-HEAP finished.');",
  "  }catch(ex){ err=(ex&&ex.message)?ex.message:String(ex);",
  "    try{ cur=0; frames.push({kind:'error',state:snap(),indices:[],focus:0,message:'ERROR: '+err}); }catch(e2){}",
  "  }",
  "  self.postMessage({frames:frames,error:err});",
  "};"
].join('\n');

/* ─────────── playback ─────────── */
var frames = [], fIdx = 0, playTimer = null, fps = 4;

function setStatus(kind, msg) {
  var el = document.getElementById('statusLine');
  var c = { none: '#666', running: '#0a58ca', correct: '#1b7f3b', wrong: '#b36b00', error: '#c00000' }[kind] || '#666';
  el.style.color = c;
  el.textContent = 'Status: ' + msg;
}

function buildLog() {
  var box = document.getElementById('traceLog');
  box.innerHTML = '';
  frames.forEach(function (f, i) {
    var s = document.createElement('span');
    s.style.display = 'block';
    s.style.cursor = 'pointer';
    s.style.padding = '1px 2px';
    s.textContent = (i + 1) + '. ' + f.message;
    s.addEventListener('click', function () { stopPlay(); showFrame(i); });
    box.appendChild(s);
  });
}

function highlightLog() {
  var box = document.getElementById('traceLog');
  for (var i = 0; i < box.children.length; i++) {
    var on = (i === fIdx);
    box.children[i].style.background = on ? '#c8e6ff' : 'transparent';
    if (on && box.children[i].scrollIntoView) box.children[i].scrollIntoView({ block: 'nearest' });
  }
}

function showFrame(k) {
  if (!frames.length) return;
  fIdx = Math.max(0, Math.min(frames.length - 1, k));
  var f = frames[fIdx];
  var last = (fIdx === frames.length - 1);
  var st = {
    values: f.state.slice(),
    focus: f.focus || 0,
    hi: f.indices || [],
    hiColor: (f.kind === 'swap') ? COL.swp : (f.kind === 'compare' ? COL.cmp : COL.focus),
    caption: ''
  };
  if (f.kind === 'compare') st.cmp = f.indices;
  if (f.kind === 'swap') st.swp = f.indices;
  if (f.kind === 'done') {
    var vio = heapViolations(f.state);
    st.viol = vio; st.badge = (vio.length === 0); st.badBadge = (vio.length > 0);
  }
  if (f.kind === 'error') { st.badBadge = true; }
  var short = f.message.length > 56 ? f.message.slice(0, 55) + '\u2026' : f.message;
  st.caption = 'frame ' + (fIdx + 1) + '/' + frames.length + ':  ' + short;
  renderScene(st);
  document.getElementById('frameCounter').textContent = (fIdx + 1) + ' of ' + frames.length;
  document.getElementById('traceCaption').textContent = f.message;
  highlightLog();
}

function pbFirst() { stopPlay(); showFrame(0); }
function pbPrev() { stopPlay(); showFrame(fIdx - 1); }
function pbNext() { stopPlay(); showFrame(fIdx + 1); }
function setSpeed(v) { fps = v; if (playTimer) { stopPlay(); pbPlay(); } }
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; }
  var b = document.getElementById('playBtn'); if (b) b.textContent = '\u25B6';
}
function pbPlay() {
  if (!frames.length) return;
  if (playTimer) { stopPlay(); return; }
  if (fIdx >= frames.length - 1) fIdx = -1;
  document.getElementById('playBtn').textContent = '\u2759\u2759';
  playTimer = setInterval(function () {
    if (fIdx >= frames.length - 1) { stopPlay(); return; }
    showFrame(fIdx + 1);
  }, Math.round(1000 / fps));
}

/* ─────────── run ─────────── */
function runCode() {
  var codeEl = document.getElementById('heapifyEditorCode');
  var raw = document.getElementById('heapifyEditorInput').value;
  var vals = raw.split(/[^0-9.\-]+/).filter(function (s) { return s.length > 0; }).map(Number);
  if (vals.length < 2 || vals.length > 15 || vals.some(function (x) { return !isFinite(x); })) {
    setStatus('error', 'enter 2–15 numbers, comma separated'); return;
  }
  stopPlay();
  setStatus('running', 'running\u2026');
  var btn = document.getElementById('runBtn'); btn.disabled = true;

  var url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' }));
  var w = new Worker(url), settled = false;

  function finish(data) {
    if (settled) return; settled = true;
    clearTimeout(to);
    try { w.terminate(); } catch (e) { }
    URL.revokeObjectURL(url);
    btn.disabled = false;
    frames = (data && data.frames && data.frames.length) ? data.frames
      : [{ kind: 'error', state: vals.slice(), indices: [], focus: 0, message: 'ERROR: no frames were produced.' }];
    buildLog(); showFrame(0);
    var lastF = frames[frames.length - 1];
    if (lastF.kind === 'error') {
      setStatus('error', lastF.message.replace(/^ERROR:\s*/, ''));
    } else {
      var vio = heapViolations(lastF.state);
      if (vio.length === 0) setStatus('correct', 'correct \u2014 every parent \u2265 its children, root = ' + lastF.state[0]);
      else setStatus('wrong', 'wrong answer \u2014 ' + (vio.length) + ' nodes violate the heap property (see final frame)');
    }
  }

  var to = setTimeout(function () {
    finish({ frames: [{ kind: 'error', state: vals.slice(), indices: [], focus: 0, message: 'ERROR: timed out after 1.5 s \u2014 infinite loop or runaway recursion?' }] });
  }, 1500);

  w.onmessage = function (ev) { finish(ev.data); };
  w.onerror = function (ev) {
    finish({ frames: [{ kind: 'error', state: vals.slice(), indices: [], focus: 0, message: 'ERROR: ' + (ev.message || 'script error in your code') }] });
  };
  w.postMessage({ code: codeEl.value, arr: vals });
}

