// @FIGURE_CODE_BEGIN
/* ─────────── canvas ─────────── */
var FW = 560, FH = 380, NR = 19, ROOTX = 285, ROOTY = 95, VGAP = 68;
var fdraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
fdraw.viewbox(0, 0, FW, FH);
var gEdge = fdraw.group(), gArr = fdraw.group(), gNode = fdraw.group(),
    gOver = fdraw.group(), gCap = fdraw.group();

var COL = { node: '#e8e8e8', ink: '#1a1a1a', focus: '#7a7a7a', cmp: '#e0a020', swp: '#2f6fb0', bad: '#c62828' };

var mkCmpEnd = fdraw.marker(6, 6, function (add) { add.path('M0,0 L6,3 L0,6 z').fill(COL.cmp); });
var mkCmpSta = fdraw.marker(6, 6, function (add) { add.path('M6,0 L0,3 L6,6 z').fill(COL.cmp); });
var mkSwpEnd = fdraw.marker(6, 6, function (add) { add.path('M0,0 L6,3 L0,6 z').fill(COL.swp); });
var mkSwpSta = fdraw.marker(6, 6, function (add) { add.path('M6,0 L0,3 L6,6 z').fill(COL.swp); });

function lbl(g, s, x, y, o) {
  o = o || {};
  var t = g.plain(String(s)).attr({
    x: x, y: y,
    'text-anchor': o.anchor || 'middle',
    'dominant-baseline': 'central'
  });
  t.font({ family: o.family || 'Georgia, serif', size: o.size || 14 });
  if (o.fill) t.fill(o.fill);
  if (o.style) t.attr('font-style', o.style);
  if (o.weight) t.attr('font-weight', o.weight);
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  return t;
}

function layoutHeap(n) {
  var pos = {}, off = [140, 70, 35, 18, 10];
  pos[1] = { x: ROOTX, y: ROOTY, d: 0 };
  for (var i = 2; i <= n; i++) {
    var p = pos[i >> 1];
    var o = off[Math.min(p.d, off.length - 1)];
    pos[i] = { x: p.x + (i % 2 === 0 ? -o : o), y: p.y + VGAP, d: p.d + 1 };
  }
  return pos;
}

function heapViolations(v) {
  var out = [], n = v.length;
  for (var i = 1; i <= n; i++) {
    for (var c = 2 * i; c <= Math.min(2 * i + 1, n); c++) {
      if (v[c - 1] > v[i - 1]) { if (out.indexOf(i) < 0) out.push(i); if (out.indexOf(c) < 0) out.push(c); }
    }
  }
  return out;
}

/* ─────────── scene renderer (state in → picture out) ─────────── */
function renderScene(st) {
  gEdge.clear(); gArr.clear(); gNode.clear(); gOver.clear(); gCap.clear();
  var v = st.values, n = v.length, pos = layoutHeap(n);
  var hi = st.hi || [], hc = st.hiColor || COL.cmp, viol = st.viol || [];

  /* ── array banner (aligned under / over the tree) ── */
  var cw = Math.min(42, 440 / n), ch = 31, y0 = 12;
  var x0 = ROOTX - (n * cw) / 2;
  lbl(gArr, 'A', x0 - 16, y0 + ch / 2, { style: 'italic', size: 19, anchor: 'end' });
  gArr.rect(n * cw, ch).move(x0, y0).fill('#f2f2f2').stroke({ color: COL.ink, width: 1.8 });
  for (var i = 1; i <= n; i++) {
    var cx = x0 + (i - 1) * cw;
    var sc = COL.ink, sw = 1.2, fl = 'none';
    if (hi.indexOf(i) >= 0) { sc = hc; sw = 2.8; fl = '#ffffff'; }
    if (st.focus === i) { sc = COL.focus; sw = 2.8; fl = '#d3d3d3'; }
    var cell = gArr.rect(cw, ch).move(cx, y0).fill(fl).stroke({ color: sc, width: sw });
    lbl(gArr, v[i - 1], cx + cw / 2, y0 + ch / 2 + 0.5, { size: 16 });
    lbl(gArr, i, cx + cw / 2, y0 + ch + 11, { size: 11, fill: '#666', family: 'sans-serif' });
    attachCell(cell, i, v);
  }

  /* ── edges ── */
  for (i = 2; i <= n; i++) {
    var a = pos[i >> 1], b = pos[i];
    gEdge.line(a.x, a.y, b.x, b.y).stroke({ color: COL.ink, width: 1.1 });
  }

  /* ── nodes ── */
  for (i = 1; i <= n; i++) {
    var p = pos[i], isF = (st.focus === i), inHi = hi.indexOf(i) >= 0, bad = viol.indexOf(i) >= 0;
    var col = inHi ? hc : (bad ? COL.bad : COL.ink);
    var wid = (inHi || bad) ? 2.6 : 1.2;
    var c = gNode.circle(NR * 2).center(p.x, p.y).fill(isF ? COL.focus : COL.node).stroke({ color: col, width: wid });
    lbl(gNode, v[i - 1], p.x, p.y + 0.5, { size: 16, fill: isF ? '#ffffff' : '#111111' });
    var isLeft = (i % 2 === 0);
    var ix = (i === 1) ? p.x : (isLeft ? p.x - NR - 2 : p.x + NR + 2);
    var iy = (i === 1) ? p.y - NR - 12 : p.y - NR - 6;
    lbl(gNode, i, ix, iy, { size: 13, fill: '#222', anchor: (i === 1) ? 'middle' : (isLeft ? 'end' : 'start'), halo: true });
    attachNode(c, i, v, n);
  }

  /* ── italic i marker: right if node is right of the root, left if left, above at the root ── */
  if (st.focus >= 1 && pos[st.focus]) {
    var pf = pos[st.focus], lx, ly, anc;
    if (pf.x > ROOTX + 1) { lx = pf.x + NR + 7; ly = pf.y; anc = 'start'; }
    else if (pf.x < ROOTX - 1) { lx = pf.x - NR - 7; ly = pf.y; anc = 'end'; }
    else { lx = pf.x - NR - 5; ly = pf.y - NR + 3; anc = 'end'; }
    if (lx < 16) { lx = pf.x + NR + 7; anc = 'start'; }
    if (lx > FW - 16) { lx = pf.x - NR - 7; anc = 'end'; }
    lbl(gOver, 'i', lx, ly, { style: 'italic', size: 17, anchor: anc, halo: true, fill: '#111' });
  }

  /* ── transient comparison / swap marks ── */
  if (st.cmp && st.cmp.length === 2 && pos[st.cmp[0]] && pos[st.cmp[1]]) drawCompare(pos[st.cmp[0]], pos[st.cmp[1]]);
  if (st.swp && st.swp.length === 2 && pos[st.swp[0]] && pos[st.swp[1]]) drawSwap(pos[st.swp[0]], pos[st.swp[1]]);

  /* ── caption strip ── */
  lbl(gCap, st.caption || '', 34, FH - 26, { anchor: 'start', size: 15, fill: '#111' });
  if (st.badge) {
    gCap.rect(236, 22).move(FW - 252, FH - 37).radius(4).fill('#eef4ee').stroke({ color: '#4a7a52', width: 1 });
    lbl(gCap, 'max-heap: every parent \u2265 its children', FW - 134, FH - 26,
      { size: 11.5, family: 'sans-serif', fill: '#1b5e20' });
  } else if (st.badBadge) {
    gCap.rect(236, 22).move(FW - 252, FH - 37).radius(4).fill('#fdeeee').stroke({ color: COL.bad, width: 1 });
    lbl(gCap, 'heap property violated (red circles)', FW - 134, FH - 26,
      { size: 11.5, family: 'sans-serif', fill: COL.bad });
  }
}

function drawCompare(a, b) {
  var dx = b.x - a.x, dy = b.y - a.y, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L, px = -uy, py = ux, k = 10;
  var x1 = a.x + ux * (NR + 3) + px * k, y1 = a.y + uy * (NR + 3) + py * k;
  var x2 = b.x - ux * (NR + 3) + px * k, y2 = b.y - uy * (NR + 3) + py * k;
  var ln = gOver.line(x1, y1, x2, y2).stroke({ color: COL.cmp, width: 1.9, dasharray: '4,3' });
  ln.marker('end', mkCmpEnd); ln.marker('start', mkCmpSta);
}

function drawSwap(a, b) {
  var mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
  var dx = b.x - a.x, dy = b.y - a.y, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L, px = -uy, py = ux;
  var s = (Math.abs(mx + px * 36 - ROOTX) > Math.abs(mx - px * 36 - ROOTX)) ? 1 : -1;
  var cxp = mx + px * 38 * s, cyp = my + py * 38 * s;
  var x1 = a.x + ux * (NR + 2), y1 = a.y + uy * (NR + 2);
  var x2 = b.x - ux * (NR + 2), y2 = b.y - uy * (NR + 2);
  var pth = gOver.path('M' + x1 + ',' + y1 + ' Q' + cxp + ',' + cyp + ' ' + x2 + ',' + y2)
    .fill('none').stroke({ color: COL.swp, width: 2.1 });
  pth.marker('end', mkSwpEnd); pth.marker('start', mkSwpSta);
}

/* ─────────── hover / click ─────────── */
function attachNode(c, i, v, n) {
  c.css('cursor', 'pointer');
  c.on('mousemove', function (e) {
    var kids = [];
    if (2 * i <= n) kids.push(v[2 * i - 1]);
    if (2 * i + 1 <= n) kids.push(v[2 * i]);
    showTooltip('index ' + i + ' \u00b7 key ' + v[i - 1] + (kids.length ? ' \u00b7 children ' + kids.join(', ') : ' \u00b7 leaf'), e);
  });
  c.on('mouseleave', hideTooltip);
  c.on('click', function () {
    showPopup('Node at index ' + i,
      'It holds key ' + v[i - 1] + '. Its parent is index ' + (i > 1 ? (i >> 1) : '\u2014') +
      ' and its children live at indices ' + (2 * i) + ' and ' + (2 * i + 1) + '. ' +
      'MAX-HEAPIFY(A, ' + i + ') compares this key with both children, swaps it with the larger child if either is bigger, and then keeps sinking from that child.');
  });
}
function attachCell(r, i, v) {
  r.css('cursor', 'pointer');
  r.on('mousemove', function (e) { showTooltip('A[' + i + '] = ' + v[i - 1] + ' \u2014 same element as tree node ' + i, e); });
  r.on('mouseleave', hideTooltip);
}

/* ─────────── static panels (a)–(f) ─────────── */
var PANELS = [
  { l: 'a', arr: [4, 1, 3, 2, 16, 9, 10, 14, 8, 7], f: 5, call: 'MAX-HEAPIFY(A, 5)' },
  { l: 'b', arr: [4, 1, 3, 2, 16, 9, 10, 14, 8, 7], f: 4, call: 'MAX-HEAPIFY(A, 4)' },
  { l: 'c', arr: [4, 1, 3, 14, 16, 9, 10, 2, 8, 7], f: 3, call: 'MAX-HEAPIFY(A, 3)' },
  { l: 'd', arr: [4, 1, 10, 14, 16, 9, 3, 2, 8, 7], f: 2, call: 'MAX-HEAPIFY(A, 2)' },
