  for (var i = 2; i <= n; i++) {
    var p = pos[i >> 1];
    var o = off[Math.min(p.d, off.length - 1)];
    pos[i] = { x: p.x + (i % 2 === 0 ? -o : o), y: p.y + VGAP, d: p.d + 1 };
