  "  var frames=[], ops=0, MAXOPS=6000, MAXFR=2500, cur=0;",
  "  function snap(){ return arr.slice(1); }",
  "  function push(kind,idx,msg){ if(frames.length>=MAXFR) throw new Error('Frame cap ('+MAXFR+') hit - is the recursion terminating?'); frames.push({kind:kind,state:snap(),indices:idx||[],focus:cur,message:msg}); }",
  "  function chk(i){ if(typeof i!=='number'||!isFinite(i)||Math.floor(i)!==i||i<1||i>n) throw new Error('Index '+i+' is outside the valid range 1..'+n); return i; }",
  "  function tick(){ if(++ops>MAXOPS) throw new Error('Operation cap ('+MAXOPS+') exceeded - runaway loop?'); }",
  "  var value=function(i){tick();chk(i);return arr[i];};",
  "  var left=function(i){tick();return 2*i;};",
  "  var right=function(i){tick();return 2*i+1;};",
  "  var compare=function(i,j){tick();chk(i);chk(j);var r=arr[i]>arr[j];push('compare',[i,j],'compare A['+i+']='+arr[i]+' with A['+j+']='+arr[j]+' \\u2192 '+r);return r;};",
  "  var swap=function(i,j){tick();chk(i);chk(j);var a=arr[i],b=arr[j];arr[i]=b;arr[j]=a;push('swap',[i,j],'swap A['+i+']='+a+' with A['+j+']='+b);};",
  "  var focus=function(i){tick();chk(i);cur=i;push('focus',[i],'focus i='+i+' (key '+arr[i]+')');};",
  "  var note=function(t){tick();push('note',[],String(t));};",
  "  var err=null;",
  "  try{",
  "    var factory=new Function('value','left','right','compare','swap','focus','note', code+'\\n;return typeof maxHeapify===\"function\"?maxHeapify:null;');",
  "    var fn=factory(value,left,right,compare,swap,focus,note);",
  "    if(!fn) throw new Error('No function named maxHeapify was found. Define: function maxHeapify(i, heapSize){ ... }');",
  "    push('start',[],'BUILD-MAX-HEAP(A): n='+n+', heapify internal nodes '+Math.floor(n/2)+' down to 1');",
  "    for(var i=Math.floor(n/2);i>=1;i--){ cur=0; note('\\u2500\\u2500 MAX-HEAPIFY(A, '+i+') \\u2500\\u2500'); fn(i,n); }",
  "    cur=0; push('done',[],'BUILD-MAX-HEAP finished.');",
  "  }catch(ex){ err=(ex&&ex.message)?ex.message:String(ex);",
  "    try{ cur=0; frames.push({kind:'error',state:snap(),indices:[],focus:0,message:'ERROR: '+err}); }catch(e2){}",
  "  }",
  "  self.postMessage({frames:frames,error:err});",
  "};"
].join('\n');

/* ─────────── playback ─────────── */
var frames = [], fIdx = 0, playTimer = null, fps = 4;

function setStatus(kind, msg) {
  var el = document.getElementById('statusLine');
  var c = { none: '#666', running: '#0a58ca', correct: '#1b7f3b', wrong: '#b36b00', error: '#c00000' }[kind] || '#666';
  el.style.color = c;
  el.textContent = 'Status: ' + msg;
}

function buildLog() {
  var box = document.getElementById('traceLog');
  box.innerHTML = '';
  frames.forEach(function (f, i) {
    var s = document.createElement('span');
    s.style.display = 'block';
    s.style.cursor = 'pointer';
    s.style.padding = '1px 2px';
    s.textContent = (i + 1) + '. ' + f.message;
    s.addEventListener('click', function () { stopPlay(); showFrame(i); });
    box.appendChild(s);
  });
}

function highlightLog() {
  var box = document.getElementById('traceLog');
  for (var i = 0; i < box.children.length; i++) {
    var on = (i === fIdx);
    box.children[i].style.background = on ? '#c8e6ff' : 'transparent';
    if (on && box.children[i].scrollIntoView) box.children[i].scrollIntoView({ block: 'nearest' });
  }
}

function showFrame(k) {
  if (!frames.length) return;
  fIdx = Math.max(0, Math.min(frames.length - 1, k));
  var f = frames[fIdx];
  var st = {
    values: f.state.slice(),
    focus: f.focus || 0,
    hi: f.indices || [],
    hiColor: (f.kind === 'swap') ? COL.swp : (f.kind === 'compare' ? COL.cmp : COL.focus),
    caption: ''
  };
  if (f.kind === 'compare') st.cmp = f.indices;
  if (f.kind === 'swap') st.swp = f.indices;
  if (f.kind === 'done') {
    var vio = heapViolations(f.state);
    st.viol = vio; st.badge = (vio.length === 0); st.badBadge = (vio.length > 0);
  }
  if (f.kind === 'error') { st.badBadge = true; }
  var short = f.message.length > 44 ? f.message.slice(0, 43) + '\u2026' : f.message;
  st.caption = 'frame ' + (fIdx + 1) + '/' + frames.length + ':  ' + short;
  renderScene(st);
  document.getElementById('frameCounter').textContent = (fIdx + 1) + ' of ' + frames.length;
  document.getElementById('traceCaption').textContent = f.message;
  highlightLog();
}

function pbFirst() { stopPlay(); showFrame(0); }
function pbPrev() { stopPlay(); showFrame(fIdx - 1); }
function pbNext() { stopPlay(); showFrame(fIdx + 1); }
function setSpeed(v) { fps = v; if (playTimer) { stopPlay(); pbPlay(); } }
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; }
  var b = document.getElementById('playBtn'); if (b) b.textContent = '\u25B6';
}
function pbPlay() {
  if (!frames.length) return;
  if (playTimer) { stopPlay(); return; }
  if (fIdx >= frames.length - 1) fIdx = -1;
  document.getElementById('playBtn').textContent = '\u2759\u2759';
  playTimer = setInterval(function () {
    if (fIdx >= frames.length - 1) { stopPlay(); return; }
    showFrame(fIdx + 1);
  }, Math.round(1000 / fps));
}

/* ─────────── run ─────────── */
function runCode() {
  var codeEl = document.getElementById('heapifyEditorCode');
  var raw = document.getElementById('heapifyEditorInput').value;
  var vals = raw.split(/[^0-9.\-]+/).filter(function (s) { return s.length > 0; }).map(Number);
  if (vals.length < 2 || vals.length > 15 || vals.some(function (x) { return !isFinite(x); })) {
    setStatus('error', 'enter 2–15 numbers, comma separated'); return;
  }
  stopPlay();
  setStatus('running', 'running\u2026');
  var btn = document.getElementById('runBtn'); btn.disabled = true;

  var url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' }));
  var w = new Worker(url), settled = false;

  function finish(data) {
    if (settled) return; settled = true;
    clearTimeout(to);
    try { w.terminate(); } catch (e) { }
    URL.revokeObjectURL(url);
    btn.disabled = false;
    frames = (data && data.frames && data.frames.length) ? data.frames
      : [{ kind: 'error', state: vals.slice(), indices: [], focus: 0, message: 'ERROR: no frames were produced.' }];
    buildLog(); showFrame(0);
    var lastF = frames[frames.length - 1];
    if (lastF.kind === 'error') {
      setStatus('error', lastF.message.replace(/^ERROR:\s*/, ''));
    } else {
      var vio = heapViolations(lastF.state);
      if (vio.length === 0) setStatus('correct', 'correct \u2014 every parent \u2265 its children, root = ' + lastF.state[0]);
      else setStatus('wrong', 'wrong answer \u2014 ' + (vio.length) + ' nodes violate the heap property (see final frame)');
    }
  }

  var to = setTimeout(function () {
    finish({ frames: [{ kind: 'error', state: vals.slice(), indices: [], focus: 0, message: 'ERROR: timed out after 1.5 s \u2014 infinite loop or runaway recursion?' }] });
  }, 1500);

  w.onmessage = function (ev) { finish(ev.data); };
  w.onerror = function (ev) {
    finish({ frames: [{ kind: 'error', state: vals.slice(), indices: [], focus: 0, message: 'ERROR: ' + (ev.message || 'script error in your code') }] });
  };
  w.postMessage({ code: codeEl.value, arr: vals });
}

/* ─────────── init ─────────── */
loadSample('sample');
goStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: BUILD-MAX-HEAP turns an arbitrary array into a max-heap by calling MAX-HEAPIFY on every internal node, working bottom-up from index ⌊n/2⌋ down to 1, so each sift-down operates on subtrees whose children are already heaps.
KEY INSIGHT (what students should walk away understanding): Going bottom-up is what makes the procedure correct and cheap: when MAX-HEAPIFY is called on node i, both of its subtrees are already max-heaps, so a single key only has to sink along one path instead of the whole tree being re-sorted.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "BUILD-MAX-HEAP turns an arbitrary array into a max-heap by calling MAX-HEAPIFY on every internal node, working bottom-up from index ⌊n/2⌋ down to 1, so each sift-down operates on subtrees whose children are already heaps.",
  "figureType": "diagram",
  "elements": [
    "Horizontal array bar labeled 'A' at the top with ten boxed cells holding the values 4, 1, 3, 2, 16, 9, 10, 14, 8, 7",
    "Index tick labels 1–10 above or below the array cells",
    "Binary tree drawn as a complete heap of 10 nodes: root at index 1, children of i at 2i and 2i+1",
    "Circular nodes containing key values, light gray fill with dark outline",
    "Small numeral outside each node showing its array index (1–10)",
    "Straight edges connecting each parent node to its left and right children",
    "Dark gray highlighted node marking the current index i being heapified",
    "Italic label 'i' placed beside the dark gray node",
    "Comparison arrows / brackets from node i to its left and right children during a comparison step",
    "Swap indication: two-headed arc between the parent and the chosen child when values exchange",
    "Panel caption text (a)–(f) indicating the six stages of BUILD-MAX-HEAP",
    "Status line showing the current call, e.g. 'MAX-HEAPIFY(A, 5)' and the heap size n = 10",
    "Legend: light gray = untouched node, dark gray = current node i, highlighted cell in array = same node in array form",
    "Final-state badge 'max-heap: every parent ≥ its children' shown when the build completes"
  ],
  "interactions": [
    {
      "id": "heapifyEditor",
      "type": "code_editor",
      "teaches": "That MAX-HEAPIFY is a sift-down loop that compares a node with both children, swaps with the largest, and recurses — and that getting the comparison or the recursion index wrong leaves a visible heap violation in the tree",
      "label": "Implement MAX-HEAPIFY, then run BUILD-MAX-HEAP",
      "entry_point": "maxHeapify(i, heapSize)",
      "api": [
        {
          "op": "value(i)",
          "does": "read the key stored at array index i (1-based)"
        },
        {
          "op": "left(i)",
          "does": "return index 2i"
        },
        {
          "op": "right(i)",
          "does": "return index 2i+1"
        },
        {
          "op": "compare(i, j)",
          "does": "record a comparison between indices i and j (draws the comparison arrow) and return true when value(i) > value(j)"
        },
        {
          "op": "swap(i, j)",
          "does": "exchange the keys at indices i and j — the ONLY way to mutate the heap"
        },
        {
          "op": "focus(i)",
          "does": "shade index i dark gray as the current node i"
        },
        {
          "op": "note(text)",
          "does": "attach the learner's own caption to the current frame"
        }
      ],
      "frame": "the whole 10-element array plus the tree, with the focused index shaded dark gray and the 1–2 indices touched by the op highlighted (comparison arrow or swap arc)",
      "input": {
        "label": "Initial array A",
        "default": "4, 1, 3, 2, 16, 9, 10, 14, 8, 7"
      },
      "sample_code": "function maxHeapify(i, heapSize) {\n  focus(i);\n  const l = left(i), r = right(i);\n  let largest = i;\n  if (l <= heapSize && compare(l, largest)) largest = l;\n  if (r <= heapSize && compare(r, largest)) largest = r;\n  if (largest !== i) {\n    swap(i, largest);\n    maxHeapify(largest, heapSize);\n  }\n}",
      "buggy_code": "function maxHeapify(i, heapSize) {\n  focus(i);\n  const l = left(i), r = right(i);\n  let largest = i;\n  if (l <= heapSize && compare(l, largest)) largest = l;\n  if (r <= heapSize && compare(r, largest)) largest = r;\n  if (largest !== i) {\n    swap(i, largest);\n    // BUG: recurses on i instead of largest, so the key never keeps sinking\n    maxHeapify(i, heapSize);\n  }\n}",
      "success_check": "after BUILD-MAX-HEAP runs maxHeapify on i = 5,4,3,2,1, every parent's key is >= both of its children's keys (root = 16)"
    },
    {
      "id": "buildPhase",
      "type": "state",
      "teaches": "That BUILD-MAX-HEAP is a sequence of five MAX-HEAPIFY calls in decreasing index order, and that each panel (a)–(f) of the figure is the heap state just before the next call",
      "label": "BUILD-MAX-HEAP step",
      "states": [
        "a: i=5",
        "b: i=4",
        "c: i=3",
        "d: i=2",
        "e: i=1",
        "f: done"
      ],
      "default": "a: i=5"
    }
  ],
  "demo_steps": [
    {
      "title": "The array is already a tree",
      "narration": "The ten array cells map one-to-one onto a complete binary tree: index i has children 2i and 2i+1. Nothing is heap-ordered yet — the root holds 4 while 16 sits at index 5.",
      "state": {
        "buildPhase": "a: i=5"
      }
    },
    {
      "title": "Start at the last internal node, i = 5",
      "narration": "Indices 6–10 are leaves and are trivially heaps, so the first call is MAX-HEAPIFY(A, 5). Node 16 already dominates its only child 7, so nothing moves.",
      "state": {
        "buildPhase": "a: i=5"
      }
    },
    {
      "title": "i = 4: the first real sift-down",
      "narration": "At index 4 the key 2 is smaller than its children 14 and 8, so it is swapped with the larger child 14 and sinks to a leaf.",
      "state": {
        "buildPhase": "b: i=4"
      }
    },
    {
      "title": "i = 3 and i = 2: fixing higher subtrees",
      "narration": "Because every child subtree is already a max-heap, each call only has to sink one key along a single root-to-leaf path: 3 sinks past 10, then 1 sinks past 16 and 7.",
      "state": {
        "buildPhase": "d: i=2"
      }
    },
    {
      "title": "i = 1: the root sinks last",
      "narration": "The final call sifts the root key 4 down through 16 and 7, exchanging it with the larger child at each level.",
      "state": {
        "buildPhase": "e: i=1"
      }
    },
    {
      "title": "A complete max-heap",
      "narration": "No dark node remains: the largest key 16 has bubbled to the root and every parent dominates its children. Now write maxHeapify yourself and watch your version drive the same transformation — or diverge from it.",
      "state": {
        "buildPhase": "f: done"
      }
    }
  ],
  "keyInsight": "Going bottom-up is what makes the procedure correct and cheap: when MAX-HEAPIFY is called on node i, both of its subtrees are already max-heaps, so a single key only has to sink along one path instead of the whole tree being re-sorted.",
  "reconstructionNotes": "Top of the canvas: a horizontal array bar labeled italic 'A' with ten boxed cells (4, 1, 3, 2, 16, 9, 10, 14, 8, 7) and faint index numbers; the cell corresponding to the focused index is outlined in the same dark shade as the tree's current node. Below it, one large complete binary tree (not six side-by-side panels) that is re-drawn for each state: root centered at top, level 2 with indices 2 and 3, level 3 with indices 4–7, level 4 with leaves 8, 9, 10 hanging under nodes 4 and 5. Nodes are medium circles, light gray fill (#e8e8e8) with a thin black outline, key value centered inside in serif numerals; the array index is a smaller numeral just outside the circle, upper-left for left children and upper-right for right children. Edges are thin straight black lines. The node currently being heapified is filled dark gray (#7a7a7a) with white or black text and gets an italic 'i' label beside it. During a comparison frame, draw thin arrows or brackets from node i to the child being compared; during a swap frame, draw a two-headed curved arc between the two circles and briefly tint both. A caption strip beneath the tree shows the panel letter (a)–(f) and the current call text such as 'MAX-HEAPIFY(A, 5)'. Panel snapshots to reproduce: (a) root 4, level2 = 1,3, level3 = 2,16,9,10, leaves 14,8,7, i=5; (b) i=4 with 2 shaded; (c) index 4 subtree now 14 over 2 and 8, i=3; (d) index 3 subtree now 10 over 9 and 3, i=2; (e) index 2 subtree now 16 over 14 and 7 with 1 at index 10, i=1 shaded at the root; (f) final heap 16,14,10,8,7,9,3,2,4,1 with no dark node and a 'max-heap' badge. Keep the whole figure monochrome gray-scale like the textbook, using color only for the transient comparison arrows (amber) and swap arc (blue)."
}

The second image above is a screenshot of the PREVIOUS attempt's rendered output (not the source figure) — use it to see exactly what broke.
